// Generated by vibelang from src/features/actions/contract.ts; the migrate flow writes it again with each batch.
// A repository's runs (docs/features/actions.md, work notes ci-parity-run-view and ci-parity-manual-run): the one home
// of the values ChatApi's routes, the browser and the tests share. Nothing here imports a library, so every side can.
/** `GET ...?repo=<owner>/<name>`: Electric's shape of a repository's runs, the `runs` rows with an execution. */
export const ACTIONS_SHAPE_ROUTE = "/api/shapes/actions";
/** The `runs` columns the list reads: never who launched a run. */
export const ACTION_COLUMNS = [
    "id",
    "repo_id",
    "execution",
    "flow",
    "status",
    "sha",
    "ref",
    "event",
    "created_at",
    "updated_at",
];
/** What started a repository's run: a push, a pull request, or a person by hand. */
export const RUN_EVENTS = ["push", "pull_request", "manual"];
/** A repository run's states as its row holds them: settled from the engine's status when the run settles. */
export const ACTION_STATES = ["working", "done", "failed", "stopped"];
/** The engine's settled status, as a repository run's row holds it. */
export const settledState = (status) => status === "completed" ? "done" : status === "cancelled" ? "stopped" : "failed";
/** The namespace a repository run's row id is derived in (RFC 9562 version 5): from its execution id. */
export const REPO_RUN_NAMESPACE = "8b7c4e2a-1f63-4d09-9a5e-3c6f0d2b7e41";
/** How many runs the list shows: the newest. */
export const ACTIONS_LIMIT = 100;
/** How deep the route walks a run's parents to find the repository run that started it. */
export const LINEAGE_DEPTH = 16;
/** `/$owner/$repo/runs`: the repository's runs. */
export const actionsPath = (owner, name) => `/${encodeURIComponent(owner)}/${encodeURIComponent(name)}/runs`;
/** `/$owner/$repo/actions/runs/$runId`: one of its runs, read from Cloudflare. */
export const actionRunPath = (owner, name, runId) => `/${encodeURIComponent(owner)}/${encodeURIComponent(name)}/actions/runs/${encodeURIComponent(runId)}`;
/** `/api/repos/<owner>/<name>`: where a repository's routes live (src/features/repo/contract.ts `REPOS_ROUTE`). */
const reposRoute = (owner, name) => `/api/repos/${encodeURIComponent(owner)}/${encodeURIComponent(name)}`;
/**
 * `GET ...`: the repository's flows a person runs by hand, `{ flows: [{ name, title? }], defaultBranch }`, from the
 * `manual` triggers of its default branch's `.smithers/factory.json`.
 */
export const repoFlowsRoute = (owner, name) => `${reposRoute(owner, name)}/flows`;
/** `GET ...?ref=<branch>`: flow `flow`'s inputs at the branch's head, `{ inputs, sha }`, as JSON Schema. */
export const flowInputsRoute = (owner, name, flow) => `${repoFlowsRoute(owner, name)}/${encodeURIComponent(flow)}`;
/**
 * `POST ...`: a run by hand, `{ id, flow, ref, input }`, or a run again, `{ id, retryOf, failed }`; `202 { runId }`, or
 * `200` the same for an id it took before.
 */
export const repoRunsRoute = (owner, name) => `${reposRoute(owner, name)}/runs`;
/** A run's execution id from the request's `id`: `<flow>:<id>`. */
export const manualExecutionId = (flow, id) => `${flow}:${id}`;
/** The most a run by hand's inputs may take as JSON, in UTF-8 bytes. */
export const MAX_INPUT_BYTES = 8 * 1024;
/**
 * Why the runs routes refused, as `{ code }`: `invalid` (400), `authentication` (401), `forbidden` (403: not a Member
 * on the repository), `not_found` (404: a repository repository flows don't run for, no such flow or branch, no such
 * run), `not_manual` (404: the flow has no `manual` trigger), `inputs` (422: the inputs don't fit the flow's form, or
 * the flow has none a form can fill), `nothing_failed` (409: Retry failed of a run with no failed job), `not_settled`
 * (409: Retry of a run still going), `conflict` (409: the request's id holds another run), `rate_limited` (429: GitHub
 * asked to wait before it says the role), `off` (503: repository flows aren't on here) and `unavailable` (503).
 */
export const RUNS_REFUSALS = [
    "invalid",
    "authentication",
    "forbidden",
    "not_found",
    "not_manual",
    "inputs",
    "nothing_failed",
    "not_settled",
    "conflict",
    "rate_limited",
    "off",
    "unavailable",
];
